import test from "node:test";
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {initial,replayEvent,reviewCandidate,p91,H,M5,type Candidate,type Event,type State} from "./stable4-offline-decision-contract";
const fx=JSON.parse(readFileSync(new URL("./stable4-offline-decision-fixture.json",import.meta.url),"utf8"));
test("P91 all 41 archived input rows: exact gross, score and eligibility; reject unclosed and missing M5",()=>{
 for(const x of fx.p91){
  assert.deepEqual(p91(x.input),x.expected);
  assert.equal(p91({...x.input,asof:x.input.signalTs+M5-1}).pass,false);
  assert.equal(p91({...x.input,bar:null}).pass,false);
 }
 assert.equal(fx.p91.filter((x:any)=>x.expected.pass).length,4);
});
for(const fee of ["10","30"]){
 test("R21 historical fill replay "+fee+"bps",()=>{
  let s=initial();const rows=fx.fills[fee];
  for(const x of rows){
   const c=x.candidate as Candidate;
   s=replayEvent(s,{type:"OBSERVED",candidate:c,ts:c.ts});
   s=replayEvent(s,{type:"OPEN",id:c.id,ts:c.ts});
   s=JSON.parse(JSON.stringify(s));
   assert.equal(reviewCandidate(s,{...c,id:c.id+"-other"},c.ts),"SLOT_OCCUPIED");
   assert.ok(x.exit>c.ts&&x.exit<=c.ts+(c.route==="R21_OLD24"?24:48)*H);
   s=replayEvent(s,{type:"FLAT_VERIFIED",id:c.id,ts:x.exit});
   assert.equal(s.cooldown[c.symbol],x.exit+12*H);
  }
  assert.equal(s.slot,null);assert.equal(s.seen.length,rows.length);
 });
}
test("pending, ambiguous and partial exposure continue occupying the slot across replay",()=>{
 const c:Candidate={id:"a",symbol:"ETHUSDT",route:"R21_OLD24",ts:200*H,gross:.3,side:"SHORT"};
 let s=replayEvent(initial(),{type:"OBSERVED",candidate:c,ts:c.ts});
 s=replayEvent(s,{type:"UNKNOWN",id:c.id,ts:c.ts+1});
 s=JSON.parse(JSON.stringify(s));
 assert.equal(reviewCandidate(s,{...c,id:"b",symbol:"SOLUSDT"},c.ts+2),"SLOT_OCCUPIED");
 assert.throws(()=>replayEvent(s,{type:"FLAT_VERIFIED",id:"a",ts:c.ts+2}),/NOT_OPEN/);
 s=replayEvent(s,{type:"OPEN",id:"a",ts:c.ts+3});
 assert.throws(()=>replayEvent(s,{type:"UNFILLED_VERIFIED",id:"a",ts:c.ts+4}),/NOT_UNFILLED/);
 s=replayEvent(s,{type:"EXIT_PENDING",id:"a",ts:c.ts+5});
 assert.equal(reviewCandidate(s,{...c,id:"b"},c.ts+6),"SLOT_OCCUPIED");
 s=replayEvent(s,{type:"FLAT_VERIFIED",id:"a",ts:c.ts+H});
 assert.equal(reviewCandidate(s,{...c,id:"b",ts:c.ts+H},c.ts+H),"COOLDOWN");
 assert.equal(reviewCandidate(s,{...c,id:"b",ts:c.ts+13*H},c.ts+13*H),"ELIGIBLE_OFFLINE");
 assert.equal(reviewCandidate(s,{...c,id:"a",ts:c.ts+13*H},c.ts+13*H),"DUPLICATE");
});
test("verified unfilled releases slot without fictitious cooldown; wrong identities and time rejected",()=>{
 const c:Candidate={id:"a",symbol:"ETHUSDT",route:"R21_NEW48",ts:200*H,gross:.3,side:"SHORT"};
 let s=replayEvent(initial(),{type:"OBSERVED",candidate:c,ts:c.ts});
 assert.throws(()=>replayEvent(s,{type:"UNFILLED_VERIFIED",id:"other",ts:c.ts+1}),/IDENTITY/);
 s=replayEvent(s,{type:"UNFILLED_VERIFIED",id:"a",ts:c.ts+1});
 assert.equal(reviewCandidate(s,{...c,id:"b"},c.ts+1),"ELIGIBLE_OFFLINE");
 assert.equal(reviewCandidate(s,{...c,id:"b",gross:.25},c.ts+1),"IDENTITY");
 assert.equal(reviewCandidate(s,{...c,id:"b"},c.ts+16*60000),"CLOCK");
});

